/* Example: styling focus for multiple elements */
button:focus, a:focus, input:focus {
    outline: 2px solid blue;
}

/* Example: changing from regular focus to focus-visible */
button:focus-visible {
    outline: 2px solid blue;
}

/* Example of feature detection for a CSS property */
@supports not (display: grid) {
    .container {
        display: flex;
    }
}

/* Example: styling focus-visible for a button */
button:focus-visible {
    outline: 3px solid orange;
    background-color: lightyellow;
}

/* Example: styling focus-visible for a link */
a:focus-visible {
    outline: 3px dashed orange;
    text-decoration: underline;
}

/* Similar: styling focus-visible for buttons */
button:focus-visible {
    outline: 3px solid purple;
    outline-offset: 2px;
}

